window.kbPageData["views/entry/k-5d77ddd66e72fa84"] = {"key":"entry/k-5d77ddd66e72fa84","state":{"route":"entry/k-5d77ddd66e72fa84"},"node":{"id":"k-5d77ddd66e72fa84","mode":"k","title":"零基预算","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["finance"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["经济"],"来源主题":["经济指标与宏观调控"],"资料类别":["非时政"]},"supplement":[{"doc":"6cbfb01fe723bba64b75","file":"《2026年政府工作报告》粉笔解读.pdf","first":29,"last":29,"relation":"辨析","evidenceId":"ca8589fd195d4c0cea82","cardId":"8f207ee51f5e40d8","questionId":null,"basis":"机构注释","quote":"2.零基预算零基预算是不考虑过去的预算项目和收支水平，以零为基点编制的预算，具体指不受以往预算安排情况的影响，一切从实际需要出发，逐项审议预算年度内各项费用的内容及其开支标准，结合财力状况，在综合平衡的基础上编制预算的一种科学的现代预算编制方法。","text":"编制零基预算时，根据当期的实际需要和财力重新审议项目及开支标准。上年的支出水平不能自动成为本年的预算基数。","reference":null}],"directorySummary":"编制零基预算时，根据当期的实际需要和财力重新审议项目及开支标准。上年的支出水平不能自动成为本年的预算基数。","sources":[{"id":"8f207ee51f5e40d8","label":"零基预算","topic":"经济指标与宏观调控","category":"非时政","text":"2.零基预算\n零基预算是不考虑过去的预算项目和收支水平，以零为基点编制的预算，具体指不受以\n往预算安排情况的影响，一切从实际需要出发，逐项审议预算年度内各项费用的内容及其开\n支标准，结合财力状况，在综合平衡的基础上编制预算的一种科学的现代预算编制方法。","source":{"doc":"6cbfb01fe723bba64b75","first":29,"last":29,"page":29,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"finance","title":"财政金融与宏观调控"}],"units":{"k-5d77ddd66e72fa84":[]}};
